#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut attempts = 0;
        let result = run_job(&config(5, 10, 25), &mut sleeper, || {
            attempts += 1;
            if attempts < 5 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(attempts, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut attempts = 0;
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            attempts += 1;
            Err(RetryError::Permanent("bad input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
        assert_eq!(attempts, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut attempts = 0;
        let result = run_job(&config(3, 1, 10), &mut sleeper, || {
            attempts += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("temporary".into())));
        assert_eq!(attempts, 3);
        assert_eq!(sleeper.sleeps, vec![1, 2]);
    }

    #[test]
    fn delay_growth_handles_overflow_and_saturates() {
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(4, u64::MAX, u64::MAX), &mut sleeper, || {
            Err(RetryError::Transient("temporary".into()))
        });

        assert!(result.is_err());
        assert_eq!(sleeper.sleeps, vec![u64::MAX, u64::MAX, u64::MAX]);
    }
}

